solution.solution.cpp:
#include <cstddef>
#include <cstdint>
#include <cstring>
#include <new>

class Heap
{
public:
    static constexpr std::size_t HEADER{ 16 };
    static constexpr std::size_t ALIGN{ 16 };

    explicit Heap(std::size_t capacity)
        : size{ capacity }, region{ static_cast<std::byte*>(::operator new(capacity, std::align_val_t{ 16 })) }
    {
        write(0, { capacity - HEADER, 1 });
    }
    ~Heap() { ::operator delete(region, std::align_val_t{ 16 }); }
    Heap(const Heap&) = delete;
    Heap& operator=(const Heap&) = delete;

    void* allocate(std::size_t bytes)
    {
        const std::size_t want{ bytes == 0 ? ALIGN : (bytes + ALIGN - 1) / ALIGN * ALIGN };
        for (std::size_t at{ 0 }; at < size; at = next(at))
        {
            Header h{ read(at) };
            if (!h.free || h.payload < want) continue;
            if (h.payload - want >= HEADER + ALIGN)
            {
                write(at + HEADER + want, { h.payload - want - HEADER, 1 });
                h.payload = want;
            }
            h.free = 0;
            write(at, h);
            return region + at + HEADER;
        }
        return nullptr;
    }

    void release(void* p)
    {
        if (!p) return;
        const std::size_t at{ static_cast<std::size_t>(static_cast<std::byte*>(p) - region) - HEADER };
        Header h{ read(at) };
        h.free = 1;
        write(at, h);
        // merge with the following block
        const std::size_t after{ next(at) };
        if (after < size)
        {
            const Header n{ read(after) };
            if (n.free) { h.payload += HEADER + n.payload; write(at, h); }
        }
        // merge with the preceding block
        std::size_t before{ size };
        for (std::size_t b{ 0 }; b < at; b = next(b)) before = b;
        if (before < at)
        {
            Header prev{ read(before) };
            if (prev.free) { prev.payload += HEADER + h.payload; write(before, prev); }
        }
    }

    std::size_t freeBytes() const
    {
        std::size_t total{ 0 };
        for (std::size_t at{ 0 }; at < size; at = next(at)) { const Header h{ read(at) }; if (h.free) total += h.payload; }
        return total;
    }

    std::size_t largestFree() const
    {
        std::size_t best{ 0 };
        for (std::size_t at{ 0 }; at < size; at = next(at)) { const Header h{ read(at) }; if (h.free && h.payload > best) best = h.payload; }
        return best;
    }

    std::size_t blockCount() const
    {
        std::size_t n{ 0 };
        for (std::size_t at{ 0 }; at < size; at = next(at)) ++n;
        return n;
    }

    bool validate() const
    {
        std::size_t at{ 0 };
        bool previousFree{ false };
        while (at < size)
        {
            const Header h{ read(at) };
            if (h.payload % ALIGN != 0 || at + HEADER + h.payload > size) return false;
            if (h.free && previousFree) return false;
            previousFree = h.free != 0;
            at = next(at);
        }
        return at == size;
    }

private:
    struct Header { std::uint64_t payload; std::uint64_t free; };

    std::size_t size;
    std::byte* region;

    Header read(std::size_t at) const { Header h; std::memcpy(&h, region + at, sizeof(h)); return h; }
    void write(std::size_t at, const Header& h) { std::memcpy(region + at, &h, sizeof(h)); }
    std::size_t next(std::size_t at) const { return at + HEADER + read(at).payload; }
};

unitTests:
#include <cstdint>
#include <cstring>
#include <vector>
static std::uintptr_t addr(const void* p) { return reinterpret_cast<std::uintptr_t>(p); }

TEST("a fresh heap") {
    Heap heap{ 1024 };
    CHECK_EQ(heap.blockCount(), 1u);
    CHECK_EQ(heap.freeBytes(), 1008u);
    CHECK_EQ(heap.largestFree(), 1008u);
    CHECK(heap.validate());
}
TEST("allocate splits the first fit") {
    Heap heap{ 1024 };
    void* a{ heap.allocate(10) };
    void* b{ heap.allocate(32) };
    CHECK(a != nullptr); CHECK(b != nullptr);
    CHECK_EQ(addr(a) % 16, 0u);
    CHECK_EQ(addr(b) - addr(a), 32u);
    CHECK_EQ(heap.blockCount(), 3u);
    CHECK_EQ(heap.freeBytes(), 1008u - 16 - 16 - 32 - 16);
    CHECK(heap.validate());
    std::memset(a, 0xAB, 16);
    std::memset(b, 0xCD, 32);
    CHECK(heap.validate());
}
TEST("small leftovers are not split off") {
    Heap heap{ 64 };
    void* a{ heap.allocate(32) };
    CHECK(a != nullptr);
    CHECK_EQ(heap.blockCount(), 1u);
    CHECK_EQ(heap.freeBytes(), 0u);
    CHECK(heap.allocate(1) == nullptr);
    heap.release(a);
    CHECK_EQ(heap.freeBytes(), 48u);
    CHECK(heap.validate());
}
TEST("freeing joins neighbours") {
    Heap heap{ 1024 };
    void* a{ heap.allocate(64) };
    void* b{ heap.allocate(64) };
    void* c{ heap.allocate(64) };
    heap.allocate(64);
    heap.release(a);
    heap.release(c);
    CHECK(heap.validate());
    CHECK_EQ(heap.largestFree(), 1008u - 4 * 80);
    heap.release(b);
    CHECK(heap.validate());
    CHECK_EQ(heap.largestFree(), 1008u - 4 * 80);
    CHECK_EQ(heap.blockCount(), 3u);
    CHECK_EQ(heap.freeBytes(), 1008u - 80 - 16);
    void* big{ heap.allocate(64 * 3 + 32) };
    CHECK(big == a);
}
TEST("everything freed is one block again") {
    Heap heap{ 2048 };
    std::vector<void*> blocks;
    for (std::size_t n : { 8u, 100u, 33u, 512u, 16u, 200u }) blocks.push_back(heap.allocate(n));
    for (void* p : blocks) CHECK(p != nullptr);
    for (std::size_t i : { 3u, 0u, 5u, 1u, 4u, 2u }) { heap.release(blocks[i]); CHECK(heap.validate()); }
    CHECK_EQ(heap.blockCount(), 1u);
    CHECK_EQ(heap.largestFree(), 2032u);
    heap.release(nullptr);
    CHECK(heap.validate());
}
TEST("fragmentation and running out") {
    Heap heap{ 512 };
    std::vector<void*> blocks;
    while (void* p{ heap.allocate(16) }) blocks.push_back(p);
    CHECK_EQ(blocks.size(), 16u);
    for (std::size_t i{ 0 }; i < blocks.size(); i += 2) heap.release(blocks[i]);
    CHECK_EQ(heap.freeBytes(), 128u);
    CHECK_EQ(heap.largestFree(), 16u);
    CHECK(heap.allocate(32) == nullptr);
    CHECK(heap.validate());
}

